# Let us compute it precisely
import csv

catalog = {}
with open('/app/dataset/product_catalog.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        pid = row['product_id']
        ean = row['ean_code']
        try:
            price = float(row['unit_price'].replace(',', '.'))
        except:
            price = float(row['unit_price'])
        cat = row['storage_category']
        catalog[pid] = {'price': price, 'cat': cat}
        catalog[ean] = {'price': price, 'cat': cat}

excluded_batch_time = '2023-07-18 03:17:00'
total_revenue = 0
excluded = 0

with open('/app/dataset/warehouse_dispatches.csv') as f:
    reader = csv.DictReader(f)
    for row in reader:
        dt = row['timestamp']
        pid = row['product_id']
        qty = int(float(row['quantity']))
        c = catalog.get(pid, catalog.get(row['product_id']))
        if 'price' not in locals():
            pass
        # better lookup
        c = catalog.get(pid)
        if c is None:
            c = catalog.get(row['product_id'])
        if c is None:
            # try by original
            c = {'price': 0}
        revenue = qty * c['price']
        if dt == excluded_batch_time:
            excluded += revenue
        else:
            total_revenue += revenue

print(total_revenue)
